function pickAspectRatio(w, h) {
  const r = w / h;
  const choices = [
    ['1:1', 1], ['5:4', 5 / 4], ['4:3', 4 / 3], ['3:2', 3 / 2], ['16:9', 16 / 9],
    ['4:5', 4 / 5], ['3:4', 3 / 4], ['2:3', 2 / 3], ['9:16', 9 / 16],
  ];
  let best = '4:3';
  let bestDelta = Infinity;
  for (const [label, ratio] of choices) {
    const delta = Math.abs(Math.log(r / ratio));
    if (delta < bestDelta) {
      bestDelta = delta;
      best = label;
    }
  }
  return best;
}

